function renderClients(){let z=(q('clientSearch')?.value||'').toLowerCase();let a=clients.filter(c=>!c.archived&&[c.name,c.phone,c.city,c.address,c.email].join(' ').toLowerCase().includes(z));q('clientList').innerHTML=a.length?a.sort((a,b)=>(a.name||'').localeCompare(b.name||'')).map(c=>{let dc=devices.filter(d=>d.clientId===c.id).length,oc=orders.filter(o=>o.clientId===c.id&&o.status!=='Zamknięte').length;return `<div class="item"><div class="deviceHead"><div><h3>${esc(c.name)}</h3><div class="meta">${esc(c.phone||'')} • ${esc([c.address,c.city].filter(Boolean).join(', '))}<br><span class="badge">Urządzenia: ${dc}</span><span class="badge">Otwarte zlecenia: ${oc}</span></div></div><div class="quickActions"><button class="smallBtn" onclick="openClientCard('${c.id}')">Karta</button><button class="secondary smallBtn" onclick="openClient('${c.id}')">Edytuj</button>${c.phone?`<a class="btn infoBtn" href="tel:${esc(c.phone)}">📞 Zadzwoń</a><a class="btn secondary" href="sms:${esc(c.phone)}">💬 SMS</a>`:''}<button class="secondary smallBtn" onclick="navigateClient('${c.id}')">🗺 Nawiguj</button><button class="danger smallBtn" onclick="archiveRecord('clients','${c.id}')">Do kosza</button></div></div></div>`}).join(''):'<div class="empty">Brak klientów.</div>'}
function renderDevices(){let z=(q('deviceSearch')?.value||'').toLowerCase();let a=devices.filter(d=>!d.archived&&[d.type,d.brand,d.model,d.serial,clientName(d.clientId),d.location].join(' ').toLowerCase().includes(z));q('deviceList').innerHTML=a.length?a.sort((a,b)=>clientName(a.clientId).localeCompare(clientName(b.clientId))).map(d=>{let next=inspections.filter(i=>i.deviceId===d.id&&i.status!=='Zrobiony').sort((a,b)=>(a.date||'').localeCompare(b.date||''))[0],ps=photos.filter(p=>p.deviceId===d.id);return `<div class="item info"><div class="deviceHead"><div><h3>${esc(deviceLabel(d))}</h3><div class="meta"><b>${esc(clientName(d.clientId))}</b> • ${esc(d.location||'')}<br><span class="badge ${d.status==='Sprawne'?'green':d.status==='Niesprawne'||d.status==='Do wymiany'?'red':'orange'}">${esc(d.status||'Sprawne')}</span><br>${next?`Następny przegląd: <b>${fmt(next.date)}</b>`:'Brak zaplanowanego przeglądu'} • Zdjęcia: ${ps.length}</div></div></div><div class="toolbar"><button class="smallBtn" onclick="openDeviceHistory('${d.id}')">Historia</button><button class="secondary smallBtn" onclick="openDevice('${d.id}')">Edytuj</button><button class="infoBtn smallBtn" onclick="openPhoto('${d.clientId}','${d.id}','')">📷 Zdjęcie</button><button class="purpleBtn smallBtn" onclick="openQr('${d.id}')">QR</button><button class="danger smallBtn" onclick="archiveRecord('devices','${d.id}')">Do kosza</button></div></div>`}).join(''):'<div class="empty">Brak urządzeń.</div>'}
