function addPageHomeBars(){const names={clients:'Klienci',devices:'Urządzenia',orders:'Zlecenia',calendar:'Kalendarz',employees:'Pracownicy',worktime:'Czas pracy',inspections:'Przeglądy',reports:'Raporty',settings:'Ustawienia',protocolsPage:'Protokoły',photosPage:'Zdjęcia',materialsPage:'Części / Materiały',callbacksPage:'Do oddzwonienia',knowledgePage:'Baza serwisowa',trashPage:'Kosz'};Object.entries(names).forEach(([id,name])=>{let p=q(id);if(!p||p.querySelector(':scope > .pageHomeBar'))return;let b=document.createElement('div');b.className='pageHomeBar';b.innerHTML=`<div class="sectionPageTitle"><strong>${name}</strong></div><button class="homeBack" onclick="go('dashboard')">← Strona główna</button>`;p.prepend(b)})}
function renderProtocolsPage(){let c=q('protocolsPageList');if(!c)return;let list=[...protocols].filter(p=>!p.archived).sort((a,b)=>(b.date||'').localeCompare(a.date||''));c.innerHTML=list.length?list.map(p=>{let cl=clients.find(x=>x.id===p.clientId),d=devices.find(x=>x.id===p.deviceId);return `<div class="item purple"><h3>${fmt(p.date)} — ${esc(cl?.name||'Klient')}</h3><div class="meta">${esc(d?deviceLabel(d):'')}<br>${esc(p.work||p.notes||'Protokół serwisowy')}</div><div class="toolbar"><button class="purpleBtn smallBtn" onclick="openProtocolById('${p.id}')">Otwórz protokół</button><button class="danger smallBtn" onclick="archiveRecord('protocols','${p.id}')">Do kosza</button></div></div>`}).join(''):'<div class="empty">Brak zapisanych protokołów.</div>'}
window.renderPhotosPage=()=>{let c=q('photosPageList');if(!c)return;let s=(q('photoPageSearch')?.value||'').toLowerCase().trim();let list=[...photos].filter(p=>!p.archived).sort((a,b)=>(b.createdAt||b.date||'').localeCompare(a.createdAt||a.date||''));list=list.filter(p=>{let cl=clients.find(x=>x.id===p.clientId),d=devices.find(x=>x.id===p.deviceId),txt=[cl?.name,d?deviceLabel(d):'',p.caption,p.category].join(' ').toLowerCase();return !s||txt.includes(s)});c.innerHTML=list.length?list.map(p=>{let cl=clients.find(x=>x.id===p.clientId),d=devices.find(x=>x.id===p.deviceId);return `<div class="photoCard"><img src="${photoSrc(p)}" alt="Zdjęcie"><b>${esc(cl?.name||'')}</b><div class="meta">${esc(d?deviceLabel(d):'')}<br>${esc(p.caption||p.category||'')}</div><div class="toolbar"><button class="danger smallBtn" onclick="archiveRecord('photos','${p.id}')">Do kosza</button></div></div>`}).join(''):'<div class="empty">Brak zdjęć.</div>'}
window.renderMaterialsPage=()=>{let c=q('materialsPageList');if(!c)return;let s=(q('materialsSearch')?.value||'').toLowerCase().trim(),rows=[];orders.forEach(o=>(o.materials||[]).forEach(m=>{if(!m.name)return;rows.push({name:m.name,qty:Number(m.qty||0),unitCost:Number(m.unitCost||0),order:o})}));rows=rows.filter(r=>!s||r.name.toLowerCase().includes(s)||clientName(r.order.clientId).toLowerCase().includes(s));let total=rows.reduce((sum,r)=>sum+r.qty*r.unitCost,0);c.innerHTML=`<div class="card"><div class="grid"><div><div class="label">Pozycji</div><div class="stat">${rows.length}</div></div><div><div class="label">Łączna wartość</div><div class="stat">${money(total)}</div></div></div></div><div class="card"><div class="materialSummaryRow"><b>Materiał / część</b><b>Ilość</b><b>Wartość</b><b>Zlecenie</b></div>${rows.map(r=>`<div class="materialSummaryRow"><span>${esc(r.name)}</span><span>${r.qty}</span><span>${money(r.qty*r.unitCost)}</span><span>${esc(clientName(r.order.clientId))}</span></div>`).join('')||'<div class="empty">Brak materiałów w zleceniach.</div>'}</div>`}

