window.renderCallbacks=()=>{let c=q('callbackList');if(!c)return;let s=(q('callbackSearch')?.value||'').toLowerCase(),td=today(),list=callbacks.filter(x=>!x.archived&&[clientName(x.clientId),x.subject,x.notes,x.status].join(' ').toLowerCase().includes(s)).sort((a,b)=>(a.status==='Załatwione')-(b.status==='Załatwione')||(a.date||'').localeCompare(b.date||''));c.innerHTML=list.length?list.map(x=>`<div class="item ${x.status==='Załatwione'?'ok':x.date<td?'dangerItem':'warn'}"><h3>${esc(x.subject||'Kontakt')}</h3><div class="meta"><b>${esc(clientName(x.clientId))}</b> • ${fmt(x.date)} • ${esc(x.status)}<br>${esc(x.notes||'')}</div><div class="toolbar"><button class="smallBtn" onclick="openCallback('${x.id}')">Edytuj</button>${x.status!=='Załatwione'?`<button class="okBtn smallBtn" onclick="finishCallback('${x.id}')">Załatwione</button>`:''}<button class="danger smallBtn" onclick="archiveRecord('callbacks','${x.id}')">Do kosza</button></div></div>`).join(''):'<div class="empty">Brak spraw do oddzwonienia.</div>'};
