window.openKnowledge=id=>{if(!requirePerm('knowledge',id?'edit':'add'))return;let x=knowledge.find(v=>v.id===id)||{};q('kbId').value=x.id||'';q('kbType').value=x.type||'';q('kbBrand').value=x.brand||'';q('kbModel').value=x.model||'';q('kbCode').value=x.code||'';q('kbTitle').value=x.title||'';q('kbSolution').value=x.solution||'';q('kbNotes').value=x.notes||'';openForm('knowledgeForm')};
