window.renderKnowledge=()=>{let c=q('knowledgeList');if(!c)return;let s=(q('knowledgeSearch')?.value||'').toLowerCase(),list=knowledge.filter(x=>!x.archived&&[x.type,x.brand,x.model,x.code,x.title,x.solution,x.notes].join(' ').toLowerCase().includes(s)).sort((a,b)=>(a.brand||'').localeCompare(b.brand||''));c.innerHTML=list.length?list.map(x=>`<div class="item knowledgeCard"><h3>${esc(x.title||x.code||'Wpis serwisowy')}</h3><div class="meta"><b>${esc([x.brand,x.model].filter(Boolean).join(' '))}</b>${x.code?` • Kod: <b>${esc(x.code)}</b>`:''}<br>${esc(x.solution||'').replace(/\n/g,'<br>')}${x.notes?`<br><i>${esc(x.notes)}</i>`:''}</div><div class="toolbar"><button class="secondary smallBtn" onclick="openKnowledge('${x.id}')">Edytuj</button><button class="danger smallBtn" onclick="archiveRecord('knowledge','${x.id}')">Do kosza</button></div></div>`).join(''):'<div class="empty">Brak wpisów w bazie serwisowej.</div>'};
window.archiveRecord=async(col,id)=>{let mod=COLLECTION_MODULE[col]||col;if(!requirePerm(mod,'delete'))return;if(!confirm('Przenieść ten rekord do Kosza? Dane nie zostaną skasowane.'))return;await setDoc(doc(db,col,id),{archived:true,archivedAt:new Date().toISOString()},{merge:true});await loadAll()};
