window.renderTrash=()=>{let c=q('trashList');if(!c)return;let groups=[['clients','Klient',clients],['devices','Urządzenie',devices],['orders','Zlecenie',orders],['inspections','Przegląd',inspections],['employees','Pracownik',employees],['worklogs','Czas pracy',worklogs],['absences','Nieobecność',absences],['photos','Zdjęcie',photos],['protocols','Protokół',protocols],['callbacks','Oddzwonienie',callbacks],['knowledge','Baza serwisowa',knowledge],['vehicles','Samochód',vehicles],['fuel','Tankowanie',fuel]];let rows=[];groups.forEach(([col,type,arr])=>arr.filter(x=>x.archived).forEach(x=>rows.push({col,type,x})));c.innerHTML=rows.length?rows.map(r=>{let name=r.col==='clients'?r.x.name:r.col==='devices'?deviceLabel(r.x):r.col==='orders'?r.x.title:r.col==='employees'?r.x.name:r.col==='worklogs'?`${fmt(r.x.date)} ${r.x.start||''}`:r.col==='absences'?`${r.x.type||''} ${fmt(r.x.from)}`:r.col==='photos'?(r.x.caption||r.x.category||'Zdjęcie'):r.col==='protocols'?`${fmt(r.x.date)} ${r.x.work||'Protokół'}`:r.col==='callbacks'?r.x.subject:r.col==='knowledge'?(r.x.title||r.x.code):r.col==='vehicles'?(r.x.name||r.x.reg):r.col==='fuel'?`${fmt(r.x.date)} ${money(r.x.cost)}`:r.x.type;return `<div class="item trashCard"><h3>${esc(r.type)} — ${esc(name||'')}</h3><div class="meta">Przeniesiono: ${esc((r.x.archivedAt||'').slice(0,16).replace('T',' '))}</div><button class="okBtn smallBtn" onclick="restoreRecord('${r.col}','${r.x.id}')">Przywróć</button></div>`}).join(''):'<div class="empty">Kosz jest pusty.</div>'};
window.openQr=id=>{let d=devices.find(x=>x.id===id);if(!d)return;openForm('qrForm');setTimeout(()=>{let box=q('qrBox');box.innerHTML='';let url=location.origin+location.pathname+'?device='+encodeURIComponent(id);if(window.QRCode)new QRCode(box,{text:url,width:220,height:220});else box.textContent=url;q('qrLabel').innerHTML=`<b>${esc(deviceLabel(d))}</b><br>SN: ${esc(d.serial||'—')}<br>${esc(clientName(d.clientId))}`},50)};
