window.exportFullBackup=()=>{let data={exportedAt:new Date().toISOString(),version:'8.0',clients,devices,orders,employees,worklogs,absences,inspections,photos,protocols,vehicles,trips,fuel,callbacks,knowledge};let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Serwisant_PRO_backup_'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
function renderSmartAlerts(){let td=today(),alerts=[];inspections.filter(i=>!i.archived&&i.status!=='Zrobiony'&&i.date).forEach(i=>{let d=daysBetween(td,i.date);if(d<0)alerts.push({c:'red',t:`Przegląd po terminie: ${inspectionClientName(i)} — ${fmt(i.date)}`});else if(d<=7)alerts.push({c:'',t:`Przegląd za ${d} dni: ${inspectionClientName(i)}`})});orders.filter(o=>!o.archived&&['Pilny','Awaria'].includes(o.priority)&&o.status!=='Zamknięte').forEach(o=>alerts.push({c:'red',t:`${o.priority}: ${clientName(o.clientId)} — ${o.title}`}));callbacks.filter(x=>!x.archived&&x.status!=='Załatwione'&&x.date<=td).forEach(x=>alerts.push({c:'',t:`Oddzwoń: ${clientName(x.clientId)} — ${x.subject}`}));q('smartAlerts').innerHTML=alerts.length?alerts.slice(0,12).map(a=>`<div class="v8Alert ${a.c}">${esc(a.t)}</div>`).join(''):'<div class="goodBox">Brak pilnych alertów.</div>';let warr=devices.filter(d=>!d.archived&&d.warrantyUntil).map(d=>({d,n:daysBetween(td,d.warrantyUntil)})).filter(x=>x.n>=0&&x.n<=60).sort((a,b)=>a.n-b.n);q('warrantyAlerts').innerHTML=warr.length?warr.map(x=>`<div class="v8Alert ${x.n<=14?'red':''}"><b>${esc(deviceLabel(x.d))}</b> — ${esc(clientName(x.d.clientId))}<br>Gwarancja kończy się ${fmt(x.d.warrantyUntil)} (${x.n} dni)</div>`).join(''):'<div class="goodBox">Brak gwarancji kończących się w ciągu 60 dni.</div>'}

function renderAll(){addPageHomeBars();renderDashboard();renderClients();renderDevices();renderOrders();renderCalendar();renderEmployees();renderWorkTime();renderInspections();renderReports();renderProtocolsPage();renderPhotosPage();renderMaterialsPage();renderCallbacks();renderKnowledge();renderTrash()}
